CREATE TEMPORARY VIEW dws_search_${grass_region_without_quote} AS
SELECT
    item_id
    ,CASE 
        WHEN image_id IS NOT NULL AND target_type = 'item' THEN image_id
        WHEN content_id IS NOT NULL AND target_type = 'video' THEN content_id
        ELSE 'NA'
    END AS content_id
    ,IF(is_ads = true, ads_id, 'not_ads') AS ads_id
    ,target_type AS card_type
    ,SUM(CASE WHEN operation = 'impression' THEN operation_cnt ELSE 0 END) AS imp_cnt
    ,SUM(CASE WHEN operation = 'click' THEN operation_cnt ELSE 0 END) AS click_cnt
    ,SUM(CASE WHEN operation = 'order' THEN operation_cnt ELSE 0 END) AS order_cnt
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv ELSE 0 END) AS gmv 
    ,SUM(CASE WHEN operation = 'order' THEN pc2_gmv ELSE 0 END) AS pc2_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND page_section IS NULL
    AND target_type IN ('item', 'video', 'livestream')
    AND operation IN ('impression', 'click', 'order')
    AND item_id IS NOT NULL
    AND user_id > 0
GROUP BY 1,2,3,4
UNION ALL 
SELECT
    CAST(source1_ext_item_id AS BIGINT) AS item_id
    ,IF(source1_content_id IS NOT NULL AND source1_target_type = 'video', source1_content_id, 'NA') AS content_id
    ,IF(source1_is_ads = true,source1_ads_id, 'not_ads') AS ads_id
    ,source1_target_type AS card_type
    ,NULL AS imp_cnt 
    ,NULL AS click_cnt
    ,SUM(CASE WHEN operation = 'order' THEN operation_cnt ELSE 0 END) AS order_cnt
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv ELSE 0 END) AS gmv 
    ,SUM(CASE WHEN operation = 'order' THEN pc2_gmv ELSE 0 END) AS pc2_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND source1_page_section IS NULL
    AND source1_page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND source1_target_type IN ('video', 'livestream')
    AND operation IN ('order')
    AND source1_ext_item_id IS NOT NULL
    AND user_id > 0
GROUP BY 1,2,3,4
UNION ALL 
SELECT
    CAST(source2_ext_item_id AS BIGINT) AS item_id
    ,IF(source2_content_id IS NOT NULL AND source2_target_type = 'video', source2_content_id, 'NA') AS content_id
    ,IF(source2_is_ads = true,source2_ads_id, 'not_ads') AS ads_id 
    ,source2_target_type AS card_type
    ,NULL AS imp_cnt 
    ,NULL AS click_cnt
    ,SUM(CASE WHEN operation = 'order' THEN operation_cnt ELSE 0 END) AS order_cnt
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv ELSE 0 END) AS gmv 
    ,SUM(CASE WHEN operation = 'order' THEN pc2_gmv ELSE 0 END) AS pc2_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND source2_page_section IS NULL
    AND source2_page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND source2_target_type IN ('video', 'livestream')
    AND operation IN ('order')
    AND source2_ext_item_id IS NOT NULL
    AND user_id > 0
GROUP BY 1,2,3,4;

