CREATE TEMPORARY VIEW ads_type_${grass_region_without_quote} AS
SELECT
    ads_id
    ,max(sub_product_type) AS sub_product_type
FROM
    (
        SELECT
            *,
            row_number() over (partition by ads_id,grass_region order by placement DESC) as rn
        FROM
            mp_paidads.dim_advertise__reg_s0_live
        WHERE 
            tz_type = 'local'
            AND grass_date = ${local_date}
            AND grass_region = ${grass_region}
    )
WHERE 
    rn = 1
GROUP BY
    ads_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_video_${grass_region_without_quote} AS
SELECT
    DISTINCT item_id
FROM
    video.video_mart_dim_content_item_bind_df
WHERE
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND content_type = 'shopee_video'
    AND tz_type = 'local';

--sql_divide_splitter--

CREATE TEMPORARY VIEW raw_mab_${grass_region_without_quote} AS
SELECT
    items
    ,RANK() OVER (PARTITION  BY date ORDER BY grass_date DESC) AS rank_grass_date
FROM
    search_algo.search_video_competitive_item_candidate
WHERE
    grass_region = ${grass_region}
    AND date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_mab_${grass_region_without_quote} AS
SELECT
DISTINCT
    item_id
FROM
    raw_mab_${grass_region_without_quote}
    lateral view explode(items) AS item_id
WHERE
    rank_grass_date = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_item_${grass_region_without_quote} AS
SELECT
    item_id 
    ,level1_global_be_category
    ,level1_global_be_category_id
FROM
    srdi_mart.dim_sr_data_warehouse_item
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_item_${grass_region_without_quote} AS
SELECT
    a.item_id
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,IF(d.item_id IS NOT NULL, TRUE, FALSE) AS has_video
    ,IF(e.item_id IS NOT NULL, TRUE, FALSE) AS skip_mab
    ,card_type
    ,content_id
    ,CASE 
        WHEN a.ads_id = 'not_ads' THEN 'not_ads'
        WHEN c.sub_product_type IS NOT NULL THEN c.sub_product_type
        ELSE 'NA'
    END AS sub_product_type
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv 
    ,SUM(pc2_gmv) AS pc2_gmv
FROM
    dws_search_${grass_region_without_quote} a 
    LEFT JOIN dim_item_${grass_region_without_quote} b
        ON a.item_id = b.item_id
    LEFT JOIN ads_type_${grass_region_without_quote} c 
        ON a.ads_id = c.ads_id
    LEFT JOIN dim_video_${grass_region_without_quote} d
        ON a.item_id = d.item_id 
    LEFT JOIN dim_mab_${grass_region_without_quote} e 
        ON a.item_id = e.item_id
GROUP BY 
    1,2,3,4,5,6,7,8;
    
--sql_divide_splitter--

CREATE TEMPORARY VIEW cube_data_${grass_region_without_quote} AS
SELECT
    item_id
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,has_video
    ,skip_mab
    ,IF(card_type IS NULL, '__ALL__', card_type) AS card_type
    ,IF(content_id IS NULL, '__ALL__', content_id) AS content_id
    ,IF(sub_product_type IS NULL, '__ALL__', sub_product_type) AS sub_product_type
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv 
    ,SUM(pc2_gmv) AS pc2_gmv
    ,COALESCE(SUM(click_cnt) / SUM(imp_cnt), 0)  AS ctr
    ,COALESCE(SUM(order_cnt) / SUM(click_cnt), 0) AS cr
    ,COALESCE(SUM(order_cnt) / SUM(imp_cnt), 0) AS ctr_x_cr
FROM 
    dws_item_${grass_region_without_quote}
GROUP BY GROUPING SETS (
    (item_id, level1_global_be_category, level1_global_be_category_id, has_video, skip_mab, card_type, content_id, sub_product_type)
    ,(item_id, level1_global_be_category, level1_global_be_category_id, has_video, skip_mab, card_type, content_id)
    ,(item_id, level1_global_be_category, level1_global_be_category_id, has_video, skip_mab, card_type, sub_product_type)
    ,(item_id, level1_global_be_category, level1_global_be_category_id, has_video, skip_mab, card_type)
    ,(item_id, level1_global_be_category, level1_global_be_category_id, has_video, skip_mab, content_id, sub_product_type)
    ,(item_id, level1_global_be_category, level1_global_be_category_id, has_video, skip_mab, content_id)
    ,(item_id, level1_global_be_category, level1_global_be_category_id, has_video, skip_mab, sub_product_type)
    ,(item_id, level1_global_be_category, level1_global_be_category_id, has_video, skip_mab)
);

--sql_divide_splitter--
    
CREATE TEMPORARY VIEW item_rank_data_${grass_region_without_quote} AS
SELECT
    *
    ,RANK() OVER (ORDER BY order_cnt DESC) AS item_order_rank
FROM 
    cube_data_${grass_region_without_quote}
WHERE
    card_type = '__ALL__'
    AND content_id = '__ALL__'
    AND sub_product_type = '__ALL__';

--sql_divide_splitter--

CREATE TEMPORARY VIEW content_rank_data_${grass_region_without_quote} AS
SELECT
    *
    ,RANK() OVER (PARTITION BY item_id, sub_product_type, card_type  ORDER BY ctr_x_cr DESC) AS ctr_x_cr_rank
FROM 
    cube_data_${grass_region_without_quote}
WHERE
    card_type IN ('item', 'video')
    AND content_id != '__ALL__';

--sql_divide_splitter--

CREATE TEMPORARY VIEW video_rank_data_${grass_region_without_quote} AS
SELECT
    *
FROM
    content_rank_data_${grass_region_without_quote}
WHERE
    card_type = 'video';

--sql_divide_splitter--

CREATE TEMPORARY VIEW video_dim_content_${grass_region_without_quote} AS
SELECT
    CAST(content_id AS STRING) AS content_id
    ,post_date
FROM
    video.video_mart_dim_content
WHERE
    grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND content_type = 'shopee_video';

--sql_divide_splitter--

CREATE TEMPORARY VIEW video_rank_data_dim_joined_${grass_region_without_quote} AS
SELECT
    item_id
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,has_video
    ,skip_mab
    ,card_type
    ,COALESCE(a.content_id, b.content_id) AS content_id
    ,sub_product_type
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv 
    ,pc2_gmv
    ,ctr
    ,cr
    ,ctr_x_cr
    ,ctr_x_cr_rank
    ,post_date
    ,CASE
        WHEN DATEDIFF(${local_date}, post_date) <= 13 THEN TRUE
        WHEN DATEDIFF(${local_date}, post_date) > 13 THEN FALSE
        ELSE NULL
    END is_new_video
FROM
    video_rank_data_${grass_region_without_quote} a
FULL JOIN
    video_dim_content_${grass_region_without_quote} b
ON
    a.content_id = b.content_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW total_order_cnt_${grass_region_without_quote} AS
SELECT
    SUM(order_cnt) AS total_order_cnt
FROM
    item_rank_data_${grass_region_without_quote};

