INSERT OVERWRITE TABLE srdi_mart.dws_sr_data_warehouse_search_card_mab_analysis_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
	item_id
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,has_video
    ,skip_mab
    ,card_type
    ,content_id
    ,sub_product_type
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv 
    ,pc2_gmv
    ,ctr
    ,cr
    ,ctr_x_cr
    ,NULL AS item_order_rank
    ,NULL AS item_order_quantile
    ,NULL AS image_ctr_x_cr_rank
    ,NULL AS video_ctr_x_cr_rank
    ,NULL AS item_cum_order_prop
    ,NULL AS post_date
    ,NULL AS is_new_video
FROM
    cube_data_${grass_region_without_quote}
WHERE
    (
        card_type != '__ALL__'
        OR content_id != '__ALL__'
        OR sub_product_type != '__ALL__'
    )
    AND (
        card_type NOT IN ('item', 'video')
        OR content_id = '__ALL__'
    )
UNION ALL 
SELECT
/*+ BROADCASTJOIN(total_order_cnt_${grass_region_without_quote}) */
	item_id
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,has_video
    ,skip_mab
    ,card_type
    ,content_id
    ,sub_product_type
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv 
    ,pc2_gmv
    ,ctr
    ,cr
    ,ctr_x_cr
    ,item_order_rank
    ,item_order_rank / MAX(item_order_rank) OVER (PARTITION BY card_type, content_id, sub_product_type) AS item_order_quantile
    ,NULL AS image_ctr_x_cr_rank
    ,NULL AS video_ctr_x_cr_rank
    ,SUM(order_cnt) OVER (ORDER BY item_order_rank ASC) / total_order_cnt AS item_cum_order_prop
    ,NULL AS post_date
    ,NULL AS is_new_video
FROM
    item_rank_data_${grass_region_without_quote}
JOIN
    total_order_cnt_${grass_region_without_quote}
UNION ALL 
SELECT
	item_id
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,has_video
    ,skip_mab
    ,card_type
    ,content_id
    ,sub_product_type
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv 
    ,pc2_gmv
    ,ctr
    ,cr
    ,ctr_x_cr
    ,NULL AS item_order_rank
    ,NULL AS item_order_quantile
    ,ctr_x_cr_rank AS image_ctr_x_cr_rank
    ,NULL AS video_ctr_x_cr_rank
    ,NULL AS item_cum_order_prop
    ,NULL AS post_date
    ,NULL AS is_new_video
FROM
    content_rank_data_${grass_region_without_quote}
WHERE
    card_type = 'item'
UNION ALL 
SELECT
	item_id
    ,level1_global_be_category
    ,level1_global_be_category_id
    ,has_video
    ,skip_mab
    ,card_type
    ,content_id
    ,sub_product_type
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv 
    ,pc2_gmv
    ,ctr
    ,cr
    ,ctr_x_cr
    ,NULL AS item_order_rank
    ,NULL AS item_order_quantile
    ,NULL AS image_ctr_x_cr_rank
    ,ctr_x_cr_rank AS video_ctr_x_cr_rank
    ,NULL AS item_cum_order_prop
    ,CAST(post_date AS DATE) AS post_date
    ,is_new_video
FROM
    video_rank_data_dim_joined_${grass_region_without_quote};
